
/* =========================================================
   E&M TECHNOLOGIES — MASTER STYLESHEET
   Large production stylesheet
   ========================================================= */

:root {
  --em-bg: #061014;
  --em-bg-soft: #0a171c;
  --em-bg-card: #0d1d23;
  --em-bg-card-2: #10252d;
  --em-text: #f5fbfd;
  --em-text-soft: #b6c7cc;
  --em-text-muted: #789097;
  --em-primary: #00d9ff;
  --em-primary-soft: rgba(0, 217, 255, 0.14);
  --em-accent: #ff8a00;
  --em-accent-soft: rgba(255, 138, 0, 0.14);
  --em-border: rgba(255, 255, 255, 0.09);
  --em-border-strong: rgba(0, 217, 255, 0.35);
  --em-shadow: 0 24px 70px rgba(0, 0, 0, 0.34);
  --em-shadow-soft: 0 14px 40px rgba(0, 0, 0, 0.22);
  --em-radius-sm: 10px;
  --em-radius-md: 18px;
  --em-radius-lg: 28px;
  --em-radius-xl: 40px;
  --em-container: 1240px;
  --em-transition: 260ms ease;
  --em-transition-slow: 650ms cubic-bezier(.2,.8,.2,1);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  padding: 0;
  background: var(--em-bg);
  color: var(--em-text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  overflow-x: hidden;
}

body,
button,
input,
textarea,
select {
  font-family: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  border: 0;
}

img {
  display: block;
  max-width: 100%;
}

::selection {
  background: var(--em-primary);
  color: #001318;
}

::-webkit-scrollbar {
  width: 9px;
}

::-webkit-scrollbar-track {
  background: #031014;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(var(--em-primary), var(--em-accent));
  border-radius: 999px;
}

.em-page {
  min-height: 100vh;
  position: relative;
  background:
    radial-gradient(circle at 15% 10%, rgba(0,217,255,.07), transparent 28%),
    radial-gradient(circle at 85% 45%, rgba(255,138,0,.05), transparent 25%),
    var(--em-bg);
}

.em-container {
  width: min(calc(100% - 40px), var(--em-container));
  margin: 0 auto;
}

.em-section {
  position: relative;
  padding: 110px 0;
}

.em-section-dark {
  background: #041015;
}

.em-section-soft {
  background: #07171d;
}

.em-muted {
  color: var(--em-text-muted);
}

.em-hidden {
  display: none !important;
}


