/* =========================================================
   NAVIGATION
   ========================================================= */

.em-navbar {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 1000;
  width: 100%;
  background: rgba(3, 12, 16, 0.76);
  border-bottom: 1px solid rgba(255,255,255,.06);
  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);
  transition: background var(--em-transition), box-shadow var(--em-transition), transform var(--em-transition);
}

.em-navbar.scrolled {
  background: rgba(3, 12, 16, .94);
  box-shadow: 0 14px 45px rgba(0,0,0,.24);
}

.em-navbar-inner {
  min-height: 82px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
}

.em-logo {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  min-width: 170px;
}

.em-logo img {
  width: 145px;
  max-height: 58px;
  object-fit: contain;
}

.em-logo-fallback {
  font-size: 22px;
  font-weight: 900;
  letter-spacing: -.05em;
}

.em-nav-links {
  display: flex;
  align-items: center;
  gap: 8px;
}

.em-nav-link {
  position: relative;
  padding: 12px 15px;
  border-radius: 12px;
  color: var(--em-text-soft);
  font-size: 14px;
  font-weight: 700;
  transition: color var(--em-transition), background var(--em-transition);
}

.em-nav-link:hover,
.em-nav-link.active {
  color: var(--em-text);
  background: rgba(255,255,255,.05);
}

.em-nav-link::after {
  content: "";
  position: absolute;
  left: 15px;
  right: 15px;
  bottom: 6px;
  height: 2px;
  transform: scaleX(0);
  transform-origin: center;
  background: linear-gradient(90deg, var(--em-primary), var(--em-accent));
  transition: transform var(--em-transition);
}

.em-nav-link:hover::after,
.em-nav-link.active::after {
  transform: scaleX(1);
}

.em-nav-cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 46px;
  padding: 0 18px;
  border-radius: 999px;
  color: #001116;
  background: linear-gradient(135deg, var(--em-primary), #74ecff);
  font-size: 13px;
  font-weight: 900;
  box-shadow: 0 12px 28px rgba(0,217,255,.18);
  transition: transform var(--em-transition), box-shadow var(--em-transition);
}

.em-nav-cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 18px 34px rgba(0,217,255,.28);
}

.em-menu-btn {
  display: none;
  width: 46px;
  height: 46px;
  align-items: center;
  justify-content: center;
  color: var(--em-text);
  background: rgba(255,255,255,.05);
  border: 1px solid var(--em-border);
  border-radius: 13px;
  cursor: pointer;
}

.em-mobile-menu {
  display: none;
  padding: 14px 20px 22px;
  border-top: 1px solid rgba(255,255,255,.06);
  background: rgba(3,12,16,.98);
}

.em-mobile-menu.open {
  display: block;
}

.em-mobile-link {
  display: block;
  padding: 14px 10px;
  border-bottom: 1px solid rgba(255,255,255,.05);
  color: var(--em-text-soft);
  font-weight: 750;
}

/* =========================================================
   HERO
   ========================================================= */

.em-hero {
  min-height: 850px;
  position: relative;
  display: flex;
  align-items: center;
  overflow: hidden;
  padding: 150px 0 100px;
}

.em-hero-grid {
  position: absolute;
  inset: 0;
  opacity: .28;
  background-image:
    linear-gradient(rgba(0,217,255,.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0,217,255,.08) 1px, transparent 1px);
  background-size: 60px 60px;
  mask-image: linear-gradient(to bottom, black, transparent 88%);
}

.em-hero-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(1px);
  pointer-events: none;
}

.em-hero-orb.one {
  width: 520px;
  height: 520px;
  left: -180px;
  top: 90px;
  background: radial-gradient(circle, rgba(0,217,255,.16), transparent 68%);
  animation: emFloatOne 9s ease-in-out infinite;
}

.em-hero-orb.two {
  width: 500px;
  height: 500px;
  right: -170px;
  bottom: 30px;
  background: radial-gradient(circle, rgba(255,138,0,.13), transparent 68%);
  animation: emFloatTwo 11s ease-in-out infinite;
}

.em-hero-content {
  position: relative;
  z-index: 2;
  max-width: 850px;
}

.em-hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 9px 14px;
  margin-bottom: 25px;
  color: #bff7ff;
  background: rgba(0,217,255,.08);
  border: 1px solid rgba(0,217,255,.25);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 850;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.em-hero-badge::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--em-primary);
  box-shadow: 0 0 18px var(--em-primary);
  animation: emPulse 1.8s ease-in-out infinite;
}

.em-hero-title {
  margin: 0;
  max-width: 920px;
  font-size: clamp(52px, 8vw, 108px);
  line-height: .92;
  letter-spacing: -.07em;
  font-weight: 950;
}

.em-gradient-text {
  background: linear-gradient(100deg, #fff 5%, #8befff 48%, #ffb25b 95%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.em-hero-description {
  max-width: 690px;
  margin: 30px 0 0;
  color: var(--em-text-soft);
  font-size: clamp(17px, 2vw, 21px);
  line-height: 1.75;
}

.em-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 13px;
  margin-top: 34px;
}

.em-btn {
  min-height: 54px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 0 22px;
  border-radius: 14px;
  font-weight: 850;
  font-size: 14px;
  cursor: pointer;
  transition: transform var(--em-transition), box-shadow var(--em-transition), border-color var(--em-transition), background var(--em-transition);
}

.em-btn:hover {
  transform: translateY(-3px);
}

.em-btn-primary {
  color: #001116;
  background: linear-gradient(135deg, var(--em-primary), #83efff);
  box-shadow: 0 16px 34px rgba(0,217,255,.18);
}

.em-btn-primary:hover {
  box-shadow: 0 20px 45px rgba(0,217,255,.28);
}

.em-btn-secondary {
  color: var(--em-text);
  background: rgba(255,255,255,.045);
  border: 1px solid var(--em-border);
}

.em-btn-secondary:hover {
  background: rgba(255,255,255,.08);
  border-color: rgba(255,255,255,.18);
}

.em-hero-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  max-width: 720px;
  margin-top: 65px;
  border-top: 1px solid var(--em-border);
  border-bottom: 1px solid var(--em-border);
}

.em-stat {
  padding: 24px 22px;
  border-right: 1px solid var(--em-border);
}

.em-stat:last-child {
  border-right: 0;
}

.em-stat-number {
  display: block;
  font-size: 31px;
  font-weight: 950;
  letter-spacing: -.04em;
}

.em-stat-label {
  display: block;
  margin-top: 7px;
  color: var(--em-text-muted);
  font-size: 12px;
  font-weight: 750;
}

/* =========================================================
   SECTION HEADERS
   ========================================================= */

.em-section-heading {
  max-width: 760px;
  margin-bottom: 52px;
}

.em-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 14px;
  color: var(--em-primary);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: .13em;
  text-transform: uppercase;
}

.em-eyebrow::before {
  content: "";
  width: 30px;
  height: 1px;
  background: linear-gradient(90deg, var(--em-primary), transparent);
}

.em-section-title {
  margin: 0;
  font-size: clamp(36px, 5vw, 64px);
  line-height: 1;
  letter-spacing: -.055em;
  font-weight: 950;
}

.em-section-description {
  max-width: 680px;
  margin: 18px 0 0;
  color: var(--em-text-soft);
  font-size: 16px;
  line-height: 1.8;
}

/* =========================================================
   ABOUT
   ========================================================= */

.em-about-grid {
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  gap: 70px;
  align-items: center;
}

.em-about-copy p {
  color: var(--em-text-soft);
  line-height: 1.9;
}

.em-about-points {
  display: grid;
  gap: 12px;
  margin-top: 28px;
}

.em-about-point {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  padding: 15px;
  border: 1px solid var(--em-border);
  border-radius: 14px;
  background: rgba(255,255,255,.025);
}

.em-about-point svg {
  flex: 0 0 auto;
  margin-top: 2px;
  color: var(--em-primary);
}

.em-about-visual {
  position: relative;
  min-height: 470px;
  border-radius: var(--em-radius-xl);
  overflow: hidden;
  border: 1px solid var(--em-border);
  background:
    radial-gradient(circle at 30% 30%, rgba(0,217,255,.18), transparent 32%),
    radial-gradient(circle at 70% 75%, rgba(255,138,0,.15), transparent 30%),
    #091b21;
  box-shadow: var(--em-shadow);
}

.em-about-visual::before,
.em-about-visual::after {
  content: "";
  position: absolute;
  border: 1px solid rgba(0,217,255,.18);
  border-radius: 50%;
}

.em-about-visual::before {
  width: 340px;
  height: 340px;
  left: 50%;
  top: 50%;
  transform: translate(-50%,-50%);
}

.em-about-visual::after {
  width: 220px;
  height: 220px;
  left: 50%;
  top: 50%;
  transform: translate(-50%,-50%);
}

.em-about-card {
  position: absolute;
  left: 11%;
  right: 11%;
  top: 50%;
  transform: translateY(-50%);
  padding: 32px;
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 25px;
  background: rgba(3,12,16,.72);
  backdrop-filter: blur(20px);
  box-shadow: 0 30px 70px rgba(0,0,0,.38);
}

.em-about-card h3 {
  margin: 0 0 10px;
  font-size: 27px;
}

.em-about-card p {
  margin: 0;
  color: var(--em-text-soft);
  line-height: 1.7;
}

/* =========================================================
   SERVICES
   ========================================================= */

.em-services-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 18px;
}

.em-service-card {
  position: relative;
  min-height: 280px;
  padding: 30px;
  overflow: hidden;
  border: 1px solid var(--em-border);
  border-radius: var(--em-radius-md);
  background: linear-gradient(145deg, rgba(255,255,255,.045), rgba(255,255,255,.018));
  transition: transform var(--em-transition-slow), border-color var(--em-transition), box-shadow var(--em-transition);
}

.em-service-card::before {
  content: "";
  position: absolute;
  width: 190px;
  height: 190px;
  right: -85px;
  top: -90px;
  border-radius: 50%;
  background: rgba(0,217,255,.1);
  transition: transform var(--em-transition-slow);
}

.em-service-card:hover {
  transform: translateY(-9px);
  border-color: var(--em-border-strong);
  box-shadow: var(--em-shadow-soft);
}

.em-service-card:hover::before {
  transform: scale(1.8);
}

.em-service-icon {
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 28px;
  color: var(--em-primary);
  background: rgba(0,217,255,.09);
  border: 1px solid rgba(0,217,255,.18);
  border-radius: 16px;
}

.em-service-card h3 {
  position: relative;
  margin: 0;
  font-size: 22px;
  letter-spacing: -.03em;
}

.em-service-card p {
  position: relative;
  margin: 13px 0 0;
  color: var(--em-text-soft);
  line-height: 1.7;
}

.em-service-arrow {
  position: absolute;
  right: 26px;
  bottom: 24px;
  color: var(--em-text-muted);
  transition: transform var(--em-transition), color var(--em-transition);
}

.em-service-card:hover .em-service-arrow {
  color: var(--em-primary);
  transform: translate(4px,-4px);
}

/* =========================================================
   WHY US
   ========================================================= */

.em-reasons-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0,1fr));
  gap: 14px;
}

.em-reason {
  padding: 26px;
  border: 1px solid var(--em-border);
  border-radius: 18px;
  background: rgba(255,255,255,.025);
}

.em-reason-number {
  color: var(--em-accent);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: .1em;
}

.em-reason h3 {
  margin: 18px 0 9px;
  font-size: 20px;
}

.em-reason p {
  margin: 0;
  color: var(--em-text-muted);
  line-height: 1.7;
}

/* =========================================================
   PORTFOLIO
   ========================================================= */

.em-filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-bottom: 30px;
}

.em-filter-btn {
  min-height: 42px;
  padding: 0 16px;
  border: 1px solid var(--em-border);
  border-radius: 999px;
  color: var(--em-text-soft);
  background: rgba(255,255,255,.035);
  cursor: pointer;
  font-size: 13px;
  font-weight: 800;
  transition: all var(--em-transition);
}

.em-filter-btn:hover,
.em-filter-btn.active {
  color: #001116;
  background: var(--em-primary);
  border-color: var(--em-primary);
}

.em-portfolio-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 18px;
}

.em-project-card {
  position: relative;
  min-height: 390px;
  overflow: hidden;
  border: 1px solid var(--em-border);
  border-radius: 22px;
  background: #08171c;
  cursor: pointer;
}

.em-project-image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 700ms cubic-bezier(.2,.8,.2,1);
}

.em-project-card::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(2,8,11,.95), rgba(2,8,11,.05) 65%);
}

.em-project-card:hover .em-project-image {
  transform: scale(1.08);
}

.em-project-content {
  position: absolute;
  z-index: 2;
  left: 24px;
  right: 24px;
  bottom: 22px;
}

.em-project-tag {
  display: inline-flex;
  padding: 6px 10px;
  margin-bottom: 10px;
  color: #c5f9ff;
  background: rgba(0,217,255,.12);
  border: 1px solid rgba(0,217,255,.2);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: .08em;
}

.em-project-content h3 {
  margin: 0;
  font-size: 24px;
}

.em-project-content p {
  margin: 7px 0 0;
  color: #bfd0d4;
  line-height: 1.5;
}

.em-project-open {
  position: absolute;
  z-index: 3;
  right: 19px;
  top: 19px;
  width: 45px;
  height: 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  border: 1px solid rgba(255,255,255,.16);
  border-radius: 50%;
  background: rgba(3,12,16,.55);
  backdrop-filter: blur(12px);
  transition: transform var(--em-transition), background var(--em-transition);
}

.em-project-card:hover .em-project-open {
  transform: rotate(8deg) scale(1.08);
  background: rgba(0,217,255,.2);
}

/* =========================================================
   IMAGE MODAL
   ========================================================= */

.em-modal-backdrop {
  position: fixed;
  z-index: 3000;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 30px;
  background: rgba(0,5,8,.88);
  backdrop-filter: blur(18px);
}

.em-modal {
  position: relative;
  width: min(1100px, 100%);
  max-height: 90vh;
  overflow: auto;
  border: 1px solid var(--em-border);
  border-radius: 24px;
  background: #071318;
  box-shadow: 0 40px 100px rgba(0,0,0,.55);
}

.em-modal img {
  width: 100%;
  max-height: 70vh;
  object-fit: contain;
  background: #02090c;
}

.em-modal-info {
  padding: 24px;
}

.em-modal-info h3 {
  margin: 0;
  font-size: 28px;
}

.em-modal-info p {
  color: var(--em-text-soft);
  line-height: 1.7;
}

.em-modal-close {
  position: absolute;
  z-index: 2;
  top: 14px;
  right: 14px;
  width: 45px;
  height: 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  background: rgba(0,0,0,.58);
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 50%;
  cursor: pointer;
}

/* =========================================================
   CTA
   ========================================================= */

.em-cta {
  position: relative;
  overflow: hidden;
  padding: 80px;
  border: 1px solid rgba(0,217,255,.2);
  border-radius: 34px;
  background:
    radial-gradient(circle at 20% 20%, rgba(0,217,255,.16), transparent 34%),
    radial-gradient(circle at 85% 80%, rgba(255,138,0,.13), transparent 30%),
    #08181e;
}

.em-cta::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(110deg, transparent 20%, rgba(255,255,255,.035) 50%, transparent 80%);
  transform: translateX(-100%);
  animation: emShine 7s linear infinite;
}

.em-cta-content {
  position: relative;
  z-index: 1;
  max-width: 820px;
}

.em-cta h2 {
  margin: 0;
  font-size: clamp(38px, 6vw, 70px);
  line-height: 1;
  letter-spacing: -.055em;
}

.em-cta p {
  margin: 20px 0 0;
  color: var(--em-text-soft);
  line-height: 1.8;
}

/* =========================================================
   CONTACT
   ========================================================= */

.em-contact-grid {
  display: grid;
  grid-template-columns: .8fr 1.2fr;
  gap: 30px;
}

.em-contact-info {
  padding: 35px;
  border: 1px solid var(--em-border);
  border-radius: 24px;
  background: rgba(255,255,255,.025);
}

.em-contact-item {
  display: flex;
  gap: 15px;
  padding: 19px 0;
  border-bottom: 1px solid rgba(255,255,255,.07);
}

.em-contact-item:last-child {
  border-bottom: 0;
}

.em-contact-icon {
  width: 46px;
  height: 46px;
  flex: 0 0 46px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--em-primary);
  background: rgba(0,217,255,.08);
  border-radius: 13px;
}

.em-contact-item strong {
  display: block;
  margin-bottom: 5px;
}

.em-contact-item span,
.em-contact-item a {
  color: var(--em-text-muted);
  line-height: 1.5;
}

.em-contact-form {
  padding: 35px;
  border: 1px solid var(--em-border);
  border-radius: 24px;
  background: rgba(255,255,255,.025);
}

.em-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0,1fr));
  gap: 16px;
}

.em-form-field {
  display: grid;
  gap: 8px;
}

.em-form-field.full {
  grid-column: 1 / -1;
}

.em-form-field label {
  color: var(--em-text-soft);
  font-size: 12px;
  font-weight: 800;
}

.em-form-field input,
.em-form-field textarea,
.em-form-field select {
  width: 100%;
  color: var(--em-text);
  background: rgba(0,0,0,.18);
  border: 1px solid var(--em-border);
  border-radius: 12px;
  outline: none;
  padding: 14px 15px;
  transition: border-color var(--em-transition), box-shadow var(--em-transition);
}

.em-form-field textarea {
  min-height: 155px;
  resize: vertical;
}

.em-form-field input::placeholder,
.em-form-field textarea::placeholder {
  color: #61777d;
}

.em-form-field input:focus,
.em-form-field textarea:focus,
.em-form-field select:focus {
  border-color: rgba(0,217,255,.55);
  box-shadow: 0 0 0 4px rgba(0,217,255,.08);
}

.em-form-submit {
  margin-top: 18px;
}

/* =========================================================
   FAQ
   ========================================================= */

.em-faq-list {
  max-width: 900px;
  display: grid;
  gap: 10px;
}

.em-faq-item {
  border: 1px solid var(--em-border);
  border-radius: 16px;
  background: rgba(255,255,255,.025);
  overflow: hidden;
}

.em-faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 20px;
  color: var(--em-text);
  background: transparent;
  text-align: left;
  font-weight: 850;
  cursor: pointer;
}

.em-faq-answer {
  padding: 0 20px 20px;
  color: var(--em-text-soft);
  line-height: 1.75;
}

/* =========================================================
   FOOTER
   ========================================================= */

.em-footer {
  padding: 70px 0 30px;
  border-top: 1px solid rgba(255,255,255,.06);
  background: #030b0e;
}

.em-footer-grid {
  display: grid;
  grid-template-columns: 1.3fr 1fr 1fr 1fr;
  gap: 40px;
}

.em-footer h4 {
  margin: 0 0 18px;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: .1em;
}

.em-footer p {
  color: var(--em-text-muted);
  line-height: 1.75;
}

.em-footer-links {
  display: grid;
  gap: 10px;
}

.em-footer-links a {
  width: fit-content;
  color: var(--em-text-muted);
  transition: color var(--em-transition), transform var(--em-transition);
}

.em-footer-links a:hover {
  color: var(--em-primary);
  transform: translateX(4px);
}

.em-footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  margin-top: 55px;
  padding-top: 22px;
  border-top: 1px solid rgba(255,255,255,.06);
  color: #61757b;
  font-size: 12px;
}

/* =========================================================
   FLOATING WHATSAPP
   ========================================================= */

.em-whatsapp {
  position: fixed;
  z-index: 2500;
  right: 24px;
  bottom: 24px;
  width: 62px;
  height: 62px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  color: #fff;
  background: #25D366;
  box-shadow: 0 16px 38px rgba(0,0,0,.34), 0 0 0 7px rgba(37,211,102,.08);
  transition: transform var(--em-transition), box-shadow var(--em-transition);
}

.em-whatsapp:hover {
  transform: translateY(-5px) scale(1.06);
  box-shadow: 0 22px 46px rgba(0,0,0,.4), 0 0 0 10px rgba(37,211,102,.1);
}

.em-whatsapp::before {
  content: "";
  position: absolute;
  inset: -8px;
  border: 1px solid rgba(37,211,102,.35);
  border-radius: 50%;
  animation: emWhatsappRing 2.2s ease-out infinite;
}

.em-whatsapp-label {
  position: absolute;
  right: 75px;
  white-space: nowrap;
  padding: 9px 13px;
  color: #fff;
  background: #0b191d;
  border: 1px solid var(--em-border);
  border-radius: 10px;
  font-size: 11px;
  font-weight: 800;
  opacity: 0;
  transform: translateX(8px);
  pointer-events: none;
  transition: all var(--em-transition);
}

.em-whatsapp:hover .em-whatsapp-label {
  opacity: 1;
  transform: translateX(0);
}

/* =========================================================
   BACK TO TOP
   ========================================================= */

.em-back-top {
  position: fixed;
  z-index: 2000;
  right: 24px;
  bottom: 98px;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--em-text);
  background: rgba(8,24,30,.86);
  border: 1px solid var(--em-border);
  border-radius: 50%;
  cursor: pointer;
  backdrop-filter: blur(12px);
  transition: transform var(--em-transition), opacity var(--em-transition);
}

.em-back-top:hover {
  transform: translateY(-3px);
}

/* =========================================================
   ANIMATIONS
   ========================================================= */

@keyframes emFloatOne {
  0%,100% { transform: translate3d(0,0,0) scale(1); }
  50% { transform: translate3d(35px,25px,0) scale(1.08); }
}

@keyframes emFloatTwo {
  0%,100% { transform: translate3d(0,0,0) scale(1); }
  50% { transform: translate3d(-30px,-25px,0) scale(1.1); }
}

@keyframes emPulse {
  0%,100% { opacity: 1; transform: scale(1); }
  50% { opacity: .45; transform: scale(.7); }
}

@keyframes emShine {
  0% { transform: translateX(-100%); }
  55%,100% { transform: translateX(100%); }
}

@keyframes emWhatsappRing {
  0% { transform: scale(.75); opacity: .75; }
  70%,100% { transform: scale(1.45); opacity: 0; }
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1100px) {
  .em-container {
    width: min(calc(100% - 34px), 1100px);
  }

  .em-about-grid {
    gap: 40px;
  }

  .em-services-grid,
  .em-portfolio-grid {
    grid-template-columns: repeat(2, minmax(0,1fr));
  }

  .em-reasons-grid {
    grid-template-columns: repeat(2, minmax(0,1fr));
  }

  .em-footer-grid {
    grid-template-columns: repeat(2, minmax(0,1fr));
  }
}

@media (max-width: 820px) {
  .em-navbar-inner {
    min-height: 72px;
  }

  .em-nav-links,
  .em-nav-cta {
    display: none;
  }

  .em-menu-btn {
    display: flex;
  }

  .em-hero {
    min-height: 760px;
    padding-top: 125px;
  }

  .em-hero-stats {
    grid-template-columns: 1fr;
  }

  .em-stat {
    border-right: 0;
    border-bottom: 1px solid var(--em-border);
  }

  .em-stat:last-child {
    border-bottom: 0;
  }

  .em-about-grid,
  .em-contact-grid {
    grid-template-columns: 1fr;
  }

  .em-about-visual {
    min-height: 390px;
  }

  .em-cta {
    padding: 48px 30px;
  }
}

@media (max-width: 620px) {
  .em-container {
    width: min(calc(100% - 26px), 100%);
  }

  .em-section {
    padding: 75px 0;
  }

  .em-hero {
    min-height: 700px;
    padding: 110px 0 70px;
  }

  .em-hero-title {
    font-size: clamp(45px, 14vw, 72px);
  }

  .em-hero-description {
    font-size: 16px;
  }

  .em-hero-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .em-btn {
    width: 100%;
  }

  .em-services-grid,
  .em-portfolio-grid,
  .em-reasons-grid,
  .em-form-grid {
    grid-template-columns: 1fr;
  }

  .em-form-field.full {
    grid-column: auto;
  }

  .em-footer-grid {
    grid-template-columns: 1fr;
  }

  .em-footer-bottom {
    flex-direction: column;
  }

  .em-whatsapp {
    right: 16px;
    bottom: 16px;
    width: 56px;
    height: 56px;
  }

  .em-back-top {
    right: 17px;
    bottom: 86px;
  }

  .em-whatsapp-label {
    display: none;
  }

  .em-modal-backdrop {
    padding: 12px;
  }

  .em-modal {
    border-radius: 17px;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}


